local function make(rows)
  if not (love and love.image and love.image.newImageData and love.graphics and love.graphics.newImage) then return nil end
  local id=love.image.newImageData(64,64)
  for y=0,63 do
    local row=rows[y+1]
    for x=0,63 do
      local n=row[x+1] or 0
      if n==0 or n==1 then
        id:setPixel(x,y,0,0,0,0)
      else
        local c=PAL[n]
        id:setPixel(x,y,c[1]/255,c[2]/255,c[3]/255,c[4]/255)
      end
    end
  end
  local img=love.graphics.newImage(id)
  if img.setFilter then pcall(img.setFilter,img,"nearest","nearest") end
  return img
end
function M.new() return setmetatable({front=nil,back=nil},M) end
function M:get(isPlayer)
  if not self.front then self.front=make(FRONT) end
  if not self.back then self.back=make(BACK) end
  return isPlayer and self.back or self.front
end
return M
